=== src/supervisor/main.c
/* supervisor — mechanism E. Shared ownership.
 *
 * A diagnostic recorder that dies silently has actively harmed its user, who believes
 * it is on duty. Any child may be kill -9'd at any time; the system degrades, logs,
 * and recovers.
 *
 * The subtle requirement: a PHYSICALLY UNPLUGGED sensor is not a crash. Restarting a
 * child in a tight loop because its hardware is gone is a restart storm, and it is the
 * failure mode most likely to appear at hour 31 of the soak.
 */
#include "common/log.h"

#include <stdio.h>

int main(void)
{
    log_init("supervisor", LOG_INFO);
    LOG_I("start");

    /* TODO(M3): fork/exec children; fd hygiene across fork; waitpid loop.
     * TODO(M3): restart policy with exponential backoff + a restart-storm guard.
     * TODO(M3): hourly heartbeat per child (log_heartbeat) — the soak plot needs it.
     * TODO(M4): degrade-not-die when a sensor is absent; distinguish absent from
     *           crashed and log the distinction. Demo day will unplug something. */

    LOG_W("not implemented — M0 scaffold");
    return 0;
}
=== src/interface/main.c
/* obdctl — query CLI over a Unix domain socket. Shared ownership.
 *
 * The handout is explicit that a crisp CLI with exact semantics beats a pretty
 * dashboard, and it is far more extensible at the live-modification station on demo
 * day. Resist the web app.
 *
 * This is the ONLY directory in src/ permitted to contain network code, and only for
 * the LAN interface (CLAUDE.md §2.1). `make boundary` enforces that.
 */
#include "common/log.h"

#include <stdio.h>
#include <string.h>

static int usage(void)
{
    fputs("usage: obdctl <verb>\n"
          "  status                     liveness, per-process RSS, event counts\n"
          "  verdicts [--since WHEN]    current and historical diagnoses\n"
          "  series PID --from --to     raw or binned history\n"
          "  baseline PID               learned model for an operating-point bin\n"
          "  faults                     detection / degradation / recovery events\n",
          stderr);
    return 2;
}

int main(int argc, char **argv)
{
    if (argc < 2) return usage();

    log_init("obdctl", LOG_WARN);

    static const char *verbs[] = { "status", "verdicts", "series", "baseline", "faults" };
    for (size_t i = 0; i < sizeof verbs / sizeof verbs[0]; i++) {
        if (strcmp(argv[1], verbs[i]) == 0) {
            /* TODO(M3): connect to the supervisor's UDS and issue the request. */
            printf("%s: not implemented — M0 scaffold\n", verbs[i]);
            return 0;
        }
    }
    return usage();
}
=== src/common/log.c
#include "common/log.h"

#include <stdarg.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

static const char  *g_component = "?";
static log_level_t  g_min       = LOG_INFO;
static data_src_t   g_src       = SRC_LIVE;

static const char *level_name(log_level_t l)
{
    switch (l) {
    case LOG_DEBUG: return "DEBUG";
    case LOG_INFO:  return "INFO";
    case LOG_WARN:  return "WARN";
    case LOG_ERROR: return "ERROR";
    case LOG_FATAL: return "FATAL";
    }
    return "?";
}

void log_init(const char *component, log_level_t min)
{
    g_component = component;
    g_min       = min;
    setvbuf(stdout, NULL, _IOLBF, 0);
}

void log_set_src(data_src_t src) { g_src = src; }
data_src_t log_get_src(void)     { return g_src; }

const char *log_src_name(data_src_t src)
{
    switch (src) {
    case SRC_LIVE:   return "live";
    case SRC_REPLAY: return "replay";
    case SRC_SYNTH:  return "synth";
    }
    return "unknown";
}

static void stamp(char *buf, size_t n)
{
    struct timespec ts;
    struct tm       tm;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0 ||
        gmtime_r(&ts.tv_sec, &tm) == NULL) {
        snprintf(buf, n, "----------T--:--:--.---Z");
        return;
    }
    size_t k = strftime(buf, n, "%Y-%m-%dT%H:%M:%S", &tm);
    snprintf(buf + k, n - k, ".%03ldZ", ts.tv_nsec / 1000000L);
}

void log_emit(log_level_t lvl, const char *fmt, ...)
{
    if (lvl < g_min) return;

    char ts[40];
    stamp(ts, sizeof ts);

    /* ts level component src pid — then the message. Greppable and column-stable. */
    printf("%s %-5s %-10s src=%-6s pid=%d ",
           ts, level_name(lvl), g_component, log_src_name(g_src), (int)getpid());

    va_list ap;
    va_start(ap, fmt);
    vprintf(fmt, ap);
    va_end(ap);

    putchar('\n');
}

/* Resident set size in KiB, from /proc/self/statm field 2 (pages). */
static long rss_kib(void)
{
    FILE *f = fopen("/proc/self/statm", "re");
    if (f == NULL) return -1;
    long total = 0, res = 0;
    int  got = fscanf(f, "%ld %ld", &total, &res);
    (void)fclose(f);
    if (got != 2) return -1;
    long page_kib = sysconf(_SC_PAGESIZE) / 1024;
    return res * page_kib;
}

void log_heartbeat(uint64_t events, uint64_t drops)
{
    log_emit(LOG_INFO, "heartbeat rss_kib=%ld events=%llu drops=%llu",
             rss_kib(), (unsigned long long)events, (unsigned long long)drops);
}

