=== src/ipc/ring.c
#include "ipc/ring.h"

#include <string.h>

#define MASK (RING_CAPACITY - 1u)

_Static_assert((RING_CAPACITY & MASK) == 0u, "RING_CAPACITY must be a power of two");

void ring_init(ring_t *r)
{
    memset(r, 0, sizeof *r);
    atomic_store_explicit(&r->head, 0, memory_order_relaxed);
    atomic_store_explicit(&r->tail, 0, memory_order_relaxed);
    atomic_store_explicit(&r->overruns, 0, memory_order_relaxed);
}

bool ring_push(ring_t *r, const ring_slot_t *in)
{
    uint64_t head = atomic_load_explicit(&r->head, memory_order_relaxed);
    uint64_t tail = atomic_load_explicit(&r->tail, memory_order_acquire);

    if (head - tail >= RING_CAPACITY) {
        /* Full. Refuse rather than overwrite: an unread sample is data the diagnosis
         * needs, and a silent overwrite is exactly the failure mechanism F exists to
         * make impossible. */
        atomic_fetch_add_explicit(&r->overruns, 1, memory_order_relaxed);
        return false;
    }

    r->slot[head & MASK] = *in;
    atomic_store_explicit(&r->head, head + 1, memory_order_release);
    return true;
}

bool ring_pop(ring_t *r, ring_slot_t *out)
{
    uint64_t tail = atomic_load_explicit(&r->tail, memory_order_relaxed);
    uint64_t head = atomic_load_explicit(&r->head, memory_order_acquire);

    if (tail == head) return false;

    *out = r->slot[tail & MASK];
    atomic_store_explicit(&r->tail, tail + 1, memory_order_release);
    return true;
}

uint64_t ring_overruns(const ring_t *r)
{
    return atomic_load_explicit(&r->overruns, memory_order_relaxed);
}

size_t ring_depth(const ring_t *r)
{
    uint64_t head = atomic_load_explicit(&r->head, memory_order_acquire);
    uint64_t tail = atomic_load_explicit(&r->tail, memory_order_acquire);
    return (size_t)(head - tail);
}
=== src/store/crc32.c
#include "store/record.h"

/* CRC-32 (IEEE 802.3, reflected). Table built on first use — no static init cost in
 * the capture path. Replaced by a hardware CRC on the Pi only if it ever shows up in
 * a profile; do not optimize this before measuring (CLAUDE.md §7.6). */
static uint32_t g_table[256];
static int      g_ready;

static void build_table(void)
{
    for (uint32_t i = 0; i < 256u; i++) {
        uint32_t c = i;
        for (int k = 0; k < 8; k++)
            c = (c & 1u) ? (0xEDB88320u ^ (c >> 1)) : (c >> 1);
        g_table[i] = c;
    }
    g_ready = 1;
}

uint32_t rec_crc32(const void *buf, uint32_t len)
{
    if (!g_ready) build_table();
    const uint8_t *p = (const uint8_t *)buf;
    uint32_t c = 0xFFFFFFFFu;
    for (uint32_t i = 0; i < len; i++)
        c = g_table[(c ^ p[i]) & 0xFFu] ^ (c >> 8);
    return c ^ 0xFFFFFFFFu;
}
=== tests/test_crc32.c
#include "store/record.h"

#include <stdio.h>
#include <string.h>

int main(void)
{
    int failures = 0;

    /* Known-answer test: CRC-32/IEEE of "123456789" is 0xCBF43926. If this ever
     * changes, the on-disk format has silently changed with it. */
    const char *v = "123456789";
    uint32_t got = rec_crc32(v, (uint32_t)strlen(v));
    if (got != 0xCBF43926u) {
        fprintf(stderr, "  FAIL crc32(\"123456789\") = 0x%08X, want 0xCBF43926\n", got);
        failures++;
    }

    if (rec_crc32("", 0) != 0u) {
        fprintf(stderr, "  FAIL crc32 of empty input must be 0\n");
        failures++;
    }

    /* A single flipped bit must change the CRC — that is the entire reason a torn
     * record is detectable on recovery. */
    char a[] = "carwatch", b[] = "carwatci";
    if (rec_crc32(a, 8) == rec_crc32(b, 8)) {
        fprintf(stderr, "  FAIL crc32 collided on a one-bit difference\n");
        failures++;
    }

    return failures == 0 ? 0 : 1;
}
=== tests/test_ring.c
/* Mechanism F is a no-drop guarantee, so the tests are about what must NOT happen:
 * an unread slot must never be overwritten, and a refusal must always be counted. */
#include "ipc/ring.h"
#include "common/log.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int failures;

#define CHECK(cond, msg) do { \
    if (!(cond)) { fprintf(stderr, "  FAIL %s:%d: %s\n", __FILE__, __LINE__, msg); \
                   failures++; } } while (0)

static ring_slot_t mk(uint64_t seq)
{
    ring_slot_t s;
    memset(&s, 0, sizeof s);
    s.seq = seq;
    s.src = (uint8_t)SRC_SYNTH;   /* test data is synthesized; label it (CLAUDE.md §2.7) */
    s.len = 8;
    return s;
}

static void test_empty_then_fifo(void)
{
    ring_t *r = malloc(sizeof *r);
    if (r == NULL) { failures++; return; }
    ring_init(r);

    ring_slot_t out;
    CHECK(!ring_pop(r, &out), "pop on empty ring must fail");
    CHECK(ring_depth(r) == 0, "empty depth");

    for (uint64_t i = 0; i < 100; i++)
        CHECK(ring_push(r, &(ring_slot_t){ .seq = i }), "push should succeed");

    CHECK(ring_depth(r) == 100, "depth after 100 pushes");

    for (uint64_t i = 0; i < 100; i++) {
        CHECK(ring_pop(r, &out), "pop should succeed");
        CHECK(out.seq == i, "FIFO order violated");
    }
    CHECK(ring_depth(r) == 0, "drained depth");
    free(r);
}

static void test_full_refuses_never_overwrites(void)
{
    ring_t *r = malloc(sizeof *r);
    if (r == NULL) { failures++; return; }
    ring_init(r);

    for (uint64_t i = 0; i < RING_CAPACITY; i++) {
        ring_slot_t s = mk(i);
        CHECK(ring_push(r, &s), "push within capacity");
    }

    ring_slot_t extra = mk(999999);
    CHECK(!ring_push(r, &extra), "push on full ring must be refused");
    CHECK(ring_overruns(r) == 1, "refusal must be counted as an overrun");

    /* The oldest unread slot must still be intact — this is the whole guarantee. */
    ring_slot_t out;
    CHECK(ring_pop(r, &out), "pop after refused push");
    CHECK(out.seq == 0, "oldest unread slot was overwritten");
    free(r);
}

static void test_wraparound(void)
{
    ring_t *r = malloc(sizeof *r);
    if (r == NULL) { failures++; return; }
    ring_init(r);

    ring_slot_t out;
    for (uint64_t i = 0; i < RING_CAPACITY * 3; i++) {
        ring_slot_t s = mk(i);
        CHECK(ring_push(r, &s), "push during wraparound");
        CHECK(ring_pop(r, &out), "pop during wraparound");
        CHECK(out.seq == i, "sequence broken across wraparound");
    }
    CHECK(ring_overruns(r) == 0, "no overruns expected in lockstep push/pop");
    free(r);
}

int main(void)
{
    test_empty_then_fifo();
    test_full_refuses_never_overwrites();
    test_wraparound();
    return failures == 0 ? 0 : 1;
}
